const fs = require('fs');
const path = require('path');

// ============================================================
// generar_473_respuestas_naturales.js
// ============================================================
// Cinco bugs de la captura, y respuestas que suenan a conversacion.
//
// 1. "EDAD: NaN MESES"
//    El calculo usaba (hoyISO || '') + 'T12:00:00'. Si hoyISO no
//    llegaba —y el flotante NUNCA lo pasaba— eso daba "T12:00:00", una
//    fecha invalida, y la resta NaN.
//    Ahora la edad se calcula en su propia funcion, que usa la fecha
//    del dispositivo si no viene la otra y devuelve null si algo falla.
//    Nunca mas "NaN meses".
//
// 2. "QUE EDAD TIENE" RESPONDIA DIAGNOSTICOS
//    La frase 'que tiene' estaba en las intenciones de enfermedades y
//    capturaba "¿que EDAD TIENE?".
//
// 3. EL ANTIPARASITARIO DE MARZO EN VEZ DEL DE AGOSTO
//    Vacunas y antiparasitarios siguen reglas DISTINTAS, y no lo
//    estaban:
//
//      Una vacuna solo la reemplaza otra del MISMO tipo: la antirrabica
//      no reemplaza a la triple felina.
//
//      Un antiparasitario reemplaza a cualquier otro, sea de la marca
//      que sea: si en agosto le diste Simparica, el Bravecto de marzo
//      ya no esta pendiente.
//
//    Sin esa distincion, el de marzo aparecia como vencido —dias
//    negativos, siempre gana— aunque ya se hubiera dado uno nuevo.
//
// 4. PREGUNTAR POR VARIOS DEVOLVIA UNO
//    "¿que antiparasitarios le he dado?" caia en el mismo camino que
//    "¿cual le toca?". Ahora hay historial completo, y se reconocen
//    "le he dado", "le di", "lleva" y "ha recibido".
//
// 5. RESPUESTAS PUNTUALES
//    Preguntar la edad devolvia la ficha entera. Ahora:
//
//      Tú: que edad tiene
//      Chiqui: Chiquito tiene 7 años y 5 meses.
//
//      Tú: esterilizado
//      Chiqui: Chiquito está registrado/a como esterilizado.
//
//      Tú: que raza es
//      Chiqui: Chiquito es Mestizo.
//
//    La ficha completa sigue estando para "¿cuales son sus datos?".
//
// Y DOS REGEX MIOS QUE ESTABAN MAL: '\\besteriliz\\b' no calzaba con
// "esterilizado" porque el \\b final exige que la palabra termine ahi.
//
// REQUISITO: script 472 desplegado.
//
// Si algo no calza, ABORTA sin escribir NADA.
// ============================================================

const RUTA_CHAT = 'components/ChiquiChat.tsx';
const RUTA_FLOT = 'components/ChiquiFlotante.tsx';
const CHAT_B64 = '';
const FLOT_B64 = '';

function abortar(motivo) {
  console.log('');
  console.log('ABORTADO: ' + motivo);
  console.log('No se modifico NINGUN archivo. Avisale a Claude lo que dice este mensaje.');
  process.exit(1);
}

const dChat = path.join(process.cwd(), RUTA_CHAT);
const dFlot = path.join(process.cwd(), RUTA_FLOT);
for (const [r, d] of [[RUTA_CHAT, dChat], [RUTA_FLOT, dFlot]]) {
  if (!fs.existsSync(d)) abortar('no se encontro ' + r + '.');
}

const actual = fs.readFileSync(dChat, 'utf8');
if (actual.includes('function calcularEdad')) {
  abortar('el chat ya tiene esto. Parece que este script ya se corrio.');
}
if (!actual.includes('estadoReproductivo')) {
  abortar('falta el script 472. Correlo primero.');
}

const chat = Buffer.from(CHAT_B64, 'base64').toString('utf8');
const flot = Buffer.from(FLOT_B64, 'base64').toString('utf8');

for (const r of ['function calcularEdad', 'historialVacunas', 'historialAntis',
                 'le he dado', 'registrado/a como']) {
  if (!chat.includes(r)) abortar('el chat nuevo no incluye [' + r + ']. Script corrupto.');
}
// La frase que capturaba la edad no puede volver.
if (chat.includes("'que tiene', 'condicion'")) {
  abortar("el chat sigue con la frase 'que tiene' en enfermedades: capturaria las preguntas de edad.");
}
console.log('  OK  la edad ya no cae en diagnosticos');

for (const r of ['masRecientePorTipo', 'soloElUltimo', 'historialAntis:']) {
  if (!flot.includes(r)) abortar('el flotante nuevo no incluye [' + r + ']. Script corrupto.');
}
// Las dos reglas tienen que aplicarse donde corresponde.
if (!flot.includes('vacunas: masRecientePorTipo(vac)')) {
  abortar('las vacunas no usan la regla por tipo.');
}
if (!flot.includes('antiparasitarios: soloElUltimo(ant)')) {
  abortar('los antiparasitarios no usan la regla del ultimo.');
}
console.log('  OK  cada uno con su regla');

fs.writeFileSync(dChat, chat, 'utf8');
console.log('');
console.log('OK: ' + RUTA_CHAT);
fs.writeFileSync(dFlot, flot, 'utf8');
console.log('OK: ' + RUTA_FLOT);
console.log('');
console.log('Prueba: "que edad tiene", "esterilizado", "que raza es",');
console.log('"que antiparasitario le toca" y "que antiparasitarios le he dado".');
console.log('');
console.log('Listo.');
